from collections import defaultdict
from string import ascii_uppercase

def generate_smallest(S1: str, S2: str) -> str:
    L1, L2 = len(S1), len(S2)
    N = L1 + L2 - 1
    S = [None] * N
    for i, c in enumerate(S2):
        if c == 'T':
            for k in range(L1):
                if S[i + k] is not None and S[i + k] != S1[k]:
                    return "-1"
                S[i + k] = S1[k]
    attached = defaultdict(list)
    for i, c in enumerate(S2):
        if c == 'F':
            last = next((q for q in range(i + L1 - 1, i - 1, -1) if S[q] is None), None)
            if last is None:
                if "".join(S[i:i + L1]) == S1:
                    return "-1"
            else:
                attached[last].append(i)
    for p in range(N):
        if S[p] is not None:
            continue
        banned = {S1[p - i] for i in attached[p]
                  if all(S[q] == S1[q - i] for q in range(i, i + L1) if q != p)}
        S[p] = next(ch for ch in ascii_uppercase if ch not in banned)
    return "".join(S)
